('200003','200','Vendas de produtos destinados à alimentação humana (Anexo I)','Vendas de produtos destinados à alimentação humana relacionados no Anexo I da Lei Complementar nº 214, de 2025, com a especificação das respectivas classificações da NCM/SH, que compõem a Cesta Básica Nacional de Alimentos, criada nos termos do art. 8º da Emenda Constitucional nº 132, de 20 de dezembro de 2023, observado o art. 125 da Lei Complementar nº 214, de 2025.',100,100,'2026-01-01',NULL,true,'{"ind_gTribRegular":0,"ind_gCredPresOper":0,"ind_gMonoPadrao":0,"ind_gMonoReten":0,"ind_gMonoRet":0,"ind_gpBioDiferenca":0,"ind_gEstornoCred":0,"tpRBSN":1,"tpDoacao":0,"indNFeABI":0,"indNFe":1,"indNFCe":1,"indCTe":0,"indCTeOS":0,"indBPe":0,"indBPeTA":0,"indBPeTM":0,"indNF3e":0,"indNFSe":0,"indNFSe Via":0,"indNFCom":0,"indNFAg":0,"indNFGas":0,"indDERE":0,"indDIR":0,"indDUIMP":1,"tipoAliquota":"Padrão","indTribRegular":0,"indCredPresOper":0,"indMonoPadrao":0,"indMonoReten":0,"indMonoRet":0}'::jsonb,'2026-10-01','https://www.planalto.gov.br/ccivil_03/leis/lcp/lcp214.htm#art125','IT2025.002-v1.71-2026-10-30'),
