('200013','200','Fornecimento de tampões higiênicos, absorventes higiênicos internos ou externos','Fornecimento de tampões higiênicos, absorventes higiênicos internos ou externos, descartáveis ou reutilizáveis, calcinhas absorventes e coletores menstruais, observado o art. 147 da Lei Complementar nº 214, de 2025.',100,100,'2026-01-01',NULL,true,'{"ind_gTribRegular":0,"ind_gCredPresOper":0,"ind_gMonoPadrao":0,"ind_gMonoReten":0,"ind_gMonoRet":0,"ind_gpBioDiferenca":0,"ind_gEstornoCred":0,"tpRBSN":1,"tpDoacao":0,"indNFeABI":0,"indNFe":1,"indNFCe":1,"indCTe":0,"indCTeOS":0,"indBPe":0,"indBPeTA":0,"indBPeTM":0,"indNF3e":0,"indNFSe":0,"indNFSe Via":0,"indNFCom":0,"indNFAg":0,"indNFGas":0,"indDERE":0,"indDIR":0,"indDUIMP":1,"tipoAliquota":"Padrão","indTribRegular":0,"indCredPresOper":0,"indMonoPadrao":0,"indMonoReten":0,"indMonoRet":0}'::jsonb,'2026-10-01','https://www.planalto.gov.br/ccivil_03/leis/lcp/lcp214.htm#art147','IT2025.002-v1.71-2026-10-30'),
('200014','200','Fornecimento dos produtos hortícolas, frutas e ovos (Anexo XV)','Fornecimento dos produtos hortícolas, frutas e ovos, relacionados no Anexo XV da Lei Complementar nº 214 , de 2025, com a especificação das respectivas classificações da NCM/SH e desde que não cozidos, observado o art. 148 da Lei Complementar nº 214, de 2025.',100,100,'2026-01-01',NULL,true,'{"ind_gTribRegular":0,"ind_gCredPresOper":0,"ind_gMonoPadrao":0,"ind_gMonoReten":0,"ind_gMonoRet":0,"ind_gpBioDiferenca":0,"ind_gEstornoCred":0,"tpRBSN":1,"tpDoacao":0,"indNFeABI":0,"indNFe":1,"indNFCe":1,"indCTe":0,"indCTeOS":0,"indBPe":0,"indBPeTA":0,"indBPeTM":0,"indNF3e":0,"indNFSe":0,"indNFSe Via":0,"indNFCom":0,"indNFAg":0,"indNFGas":0,"indDERE":0,"indDIR":0,"indDUIMP":1,"tipoAliquota":"Padrão","indTribRegular":0,"indCredPresOper":0,"indMonoPadrao":0,"indMonoReten":0,"indMonoRet":0}'::jsonb,'2026-10-01','https://www.planalto.gov.br/ccivil_03/leis/lcp/lcp214.htm#art148','IT2025.002-v1.71-2026-10-30'),
('200015','200','Venda de automóveis de passageiros de fabricação nacional adquiridos por motoristas profissionais ou pessoas com deficiência','Venda de automóveis de passageiros de fabricação nacional de, no mínimo, 4 (quatro) portas, inclusive a de acesso ao bagageiro, quando adquiridos por motoristas profissionais que exerçam, comprovadamente, em automóvel de sua propriedade, atividade de condutor autônomo de passageiros, na condição de titular de autorização, permissão ou concessão do poder público, e que destinem o automóvel à utilização na categoria de aluguel (táxi), ou por pessoas com deficiência física, visual, auditiva, deficiência mental severa ou profunda, transtorno do espectro autista, com prejuízos na comunicação social e em padrões restritos ou repetitivos de comportamento de nível moderado ou grave, nos termos da legislação relativa à matéria, observado o disposto no art. 149 da Lei Complementar nº 214, de 2025.',100,100,'2026-01-01',NULL,true,'{"ind_gTribRegular":0,"ind_gCredPresOper":0,"ind_gMonoPadrao":0,"ind_gMonoReten":0,"ind_gMonoRet":0,"ind_gpBioDiferenca":0,"ind_gEstornoCred":0,"tpRBSN":1,"tpDoacao":0,"indNFeABI":0,"indNFe":1,"indNFCe":1,"indCTe":0,"indCTeOS":0,"indBPe":0,"indBPeTA":0,"indBPeTM":0,"indNF3e":0,"indNFSe":0,"indNFSe Via":0,"indNFCom":0,"indNFAg":0,"indNFGas":0,"indDERE":0,"indDIR":0,"indDUIMP":0,"tipoAliquota":"Padrão","indTribRegular":0,"indCredPresOper":0,"indMonoPadrao":0,"indMonoReten":0,"indMonoRet":0}'::jsonb,'2026-10-01','https://www.planalto.gov.br/ccivil_03/leis/lcp/lcp214.htm#art149','IT2025.002-v1.71-2026-10-30'),
