('200040','200','Fornecimento de serviços de comunicação institucional à administração pública','Fornecimento dos seguintes serviços de comunicação institucional à administração pública direta, autarquias e fundações públicas: serviços direcionados ao planejamento, criação, programação e manutenção de páginas eletrônicas da administração pública, ao monitoramento e gestão de suas redes sociais e à otimização de páginas e canais digitais para mecanismos de buscas e produção de mensagens, infográficos, painéis interativos e conteúdo institucional, serviços de relações com a imprensa, que reúnem estratégias organizacionais para promover e reforçar a comunicação dos órgãos e das entidades contratantes com seus públicos de interesse, por meio da interação com profissionais da imprensa, e serviços de relações públicas, que compreendem o esforço de comunicação planejado, coeso e contínuo que tem por objetivo estabelecer adequada percepção da atuação e dos objetivos institucionais, a partir do estímulo à compreensão mútua e da manutenção de padrões de relacionamento e fluxos de informação entre os órgãos e as entidades contratantes e seus públicos de interesse, no País e no exterior, observado o art. 140 da Lei Complementar nº 214, de 2025.',60,60,'2026-01-01',NULL,false,'{"ind_gTribRegular":0,"ind_gCredPresOper":0,"ind_gMonoPadrao":0,"ind_gMonoReten":0,"ind_gMonoRet":0,"ind_gpBioDiferenca":0,"ind_gEstornoCred":0,"tpRBSN":1,"tpDoacao":2,"indNFeABI":0,"indNFe":0,"indNFCe":0,"indCTe":0,"indCTeOS":0,"indBPe":0,"indBPeTA":0,"indBPeTM":0,"indNF3e":0,"indNFSe":1,"indNFSe Via":0,"indNFCom":0,"indNFAg":0,"indNFGas":0,"indDERE":0,"indDIR":0,"indDUIMP":0,"tipoAliquota":"Padrão","indTribRegular":0,"indCredPresOper":0,"indMonoPadrao":0,"indMonoReten":0,"indMonoRet":0}'::jsonb,'2026-10-01','https://www.planalto.gov.br/ccivil_03/leis/lcp/lcp214.htm#art140','IT2025.002-v1.71-2026-10-30'),
